        powers = [1] * (K + 1)
        for i in range(1, K + 1):
            powers[i] = powers[i - 1] * prefix % MOD

        total = 0
        for k in range(K + 1):
            sign = 1 if (K - k) % 2 == 0 else MOD - 1
            total += binom[K][k] * powers[k] * prefix_power_sums[K - k] * sign
            total %= MOD

        ans = (ans + total) % MOD

        for k in range(K + 1):
            prefix_power_sums[k] = (prefix_power_sums[k] + powers[k]) % MOD

    print(ans)

if __name__ == "__main__":
